"""Example data: synthetic series generated by code, and the real Dingle houses (`dingle_houses`).

Why a generator and not a file: the project's real plant series belong to third parties and are not
cleared for publication (see CLAUDE.md and PROPOSTA_BIBLIOTECA.md section 8). A generator with a fixed
seed solves the licence problem, does not bloat the repository and, what matters most for testing,
lets you ask for exactly the pathology you want to exercise.

What this data is good for testing: physics (against the closed-form value), protocol (folds, windows,
support), contracts (valid vs invalid) and covariate plumbing. What it is NOT good for testing: whether
a model forecasts well. A series generated by a known process is easy or hard in the wrong way; the
ranking between models only makes sense on real data, and those numbers stay frozen in
`experimentos/testes_previsao/resultados/`.
"""

from __future__ import annotations

import hashlib
import os
from collections.abc import Callable, Iterable
from pathlib import Path
from typing import Literal

import numpy as np
import pandas as pd

from .contracts import EnergySeries, step
from .provenance import Provenance, attach, synthetic

DEFAULT_TZ = "America/Sao_Paulo"


def _clear_sky(index: pd.DatetimeIndex, *, peak: float) -> np.ndarray:
    """Simple daytime bell: half-sine between 6 h and 18 h, zero at night.

    Not a real clear-sky model (that is `physics.clear_sky_ghi`); a plausible, deterministic daytime shape
    is enough for example data, and changing it would change every test built on it.
    """
    h = index.hour + index.minute / 60.0
    day = np.clip(np.sin(np.pi * (h - 6.0) / 12.0), 0.0, None)
    return peak * day


def example_plant(
    *,
    n_series: int = 2,
    start: str = "2024-01-01",
    days: int = 120,
    freq: str = "h",
    peak_kwh: float = 3.0,
    seed: int = 42,
    cloudiness: float = 0.35,
    tz: str = DEFAULT_TZ,
) -> tuple[EnergySeries, pd.DataFrame]:
    """Synthetic PV generation and the matching weather.

    Returns (series, weather). The weather is what regime B or C would receive: `poa_clear_sky`
    (geometry, always known) and `poa_estimated` (clear sky x the day's clear-sky index). Generation is
    built AS A FUNCTION of `poa_estimated`, on purpose: that makes it possible to test whether an adapter
    really uses the covariate it received. That is how TiDE went two versions ignoring the weather
    without anyone noticing.
    """
    rng = np.random.default_rng(seed)
    idx = pd.date_range(start, periods=days * _steps_per_day(freq), freq=freq, tz=tz)
    frames, weather = [], []
    for i in range(n_series):
        uid = f"plant_{i + 1}"
        clear = _clear_sky(idx, peak=peak_kwh * (1.0 + 0.5 * i))
        # One kc per day, not per hour: cloudiness persists within the day.
        day_idx = idx.normalize()
        kc_day = pd.Series(rng.uniform(1.0 - cloudiness, 1.0, size=day_idx.nunique()), index=day_idx.unique())
        kc = day_idx.map(kc_day.to_dict()).to_numpy(dtype=float)
        poa = clear * kc
        y = poa * 0.95  # constant efficiency: the relation stays exact and testable
        frames.append(pd.DataFrame({"unique_id": uid, "ds": idx, "y": y}))
        weather.append(
            pd.DataFrame({"unique_id": uid, "ds": idx, "poa_clear_sky": clear, "poa_estimated": poa})
        )
    series = EnergySeries.from_dataframe(
        pd.concat(frames, ignore_index=True),
        unit="kWh",
        quantity="generation",
        tz=tz,
        freq=freq,
        provenance=synthetic(f"example_plant(seed={seed})"),
    )
    weather_frame = pd.concat(weather, ignore_index=True)
    return series, attach(weather_frame, synthetic(f"example_plant(seed={seed}) weather"))


def example_house(
    *,
    n_series: int = 3,
    start: str = "2024-01-01",
    days: int = 90,
    freq: str = "h",
    mean_kwh: float = 0.4,
    seed: int = 7,
    tz: str = DEFAULT_TZ,
) -> EnergySeries:
    """Synthetic residential consumption: two daily peaks, higher weekends, log-normal noise.

    The noise is skewed on purpose. Real consumption has short, tall peaks, and that is why foundation
    models ended up with a ~-20% bias on the real data: they forecast the median. A series with
    symmetric noise would hide that behaviour.
    """
    rng = np.random.default_rng(seed)
    idx = pd.date_range(start, periods=days * _steps_per_day(freq), freq=freq, tz=tz)
    h = idx.hour + idx.minute / 60.0
    shape = 0.5 + np.exp(-0.5 * ((h - 8) / 1.6) ** 2) + 1.4 * np.exp(-0.5 * ((h - 19) / 2.0) ** 2)
    weekend = np.where(idx.day_of_week >= 5, 1.25, 1.0)
    frames = []
    for i in range(n_series):
        base = mean_kwh * (0.8 + 0.4 * i) * shape * weekend
        y = base * rng.lognormal(mean=0.0, sigma=0.35, size=len(idx))
        frames.append(pd.DataFrame({"unique_id": f"house_{i + 1}", "ds": idx, "y": y}))
    return EnergySeries.from_dataframe(
        pd.concat(frames, ignore_index=True),
        unit="kWh",
        quantity="consumption",
        tz=tz,
        freq=freq,
        provenance=synthetic(f"example_house(seed={seed})"),
    )


def with_gaps(
    series: EnergySeries,
    *,
    fraction: float = 0.02,
    seed: int = 0,
    short_series: str | None = None,
    days_short: int = 20,
) -> EnergySeries:
    """Introduce the pathologies the real data has, so tests can exercise them.

    - `fraction`: steps with no record (y null, `valid` False). A gap is not a zero.
    - `short_series`: makes one of the series end `days_short` days before the others. It is the case of
      house H14 in the real data, which made `cross_validation` re-emit days of an earlier fold with a
      model trained after them. Any new protocol should be tested against this.
    """
    if not 0.0 <= fraction < 1.0:
        raise ValueError("fraction must be in [0, 1)")
    rng = np.random.default_rng(seed)
    x = series.frame.copy()
    if fraction > 0:
        target = rng.random(len(x)) < fraction
        x.loc[target, "y"] = np.nan
        x.loc[target, "valid"] = False
    if short_series is not None:
        if short_series not in set(x["unique_id"]):
            raise ValueError(f"series '{short_series}' does not exist: {sorted(set(x['unique_id']))}")
        cut = x.loc[x["unique_id"] == short_series, "ds"].max() - pd.Timedelta(days=days_short)
        out = (x["unique_id"] == short_series) & (x["ds"] > cut)
        x = x.loc[~out].reset_index(drop=True)
    return EnergySeries.from_dataframe(
        x,
        unit=series.unit,
        quantity=series.quantity,
        tz=series.tz,
        freq=series.freq,
        provenance=series.provenance,
    )


def perfect_forecast(series: EnergySeries) -> pd.DataFrame:
    """Forecast equal to the actual values: skill 1 by construction. Useful to check metric signs."""
    v = series.valid_only()
    return v[["unique_id", "ds"]].assign(yhat=v["y"].to_numpy())


def persistence_forecast(series: EnergySeries, *, lag_h: int = 24) -> pd.DataFrame:
    """The "same as yesterday" reference: the value at the same time `lag_h` hours earlier."""
    v = series.valid_only().sort_values(["unique_id", "ds"], kind="stable")
    parts = []
    for uid, g in v.groupby("unique_id"):
        s = g.set_index("ds")["y"]
        parts.append(
            pd.DataFrame(
                {
                    "unique_id": uid,
                    "ds": s.index,
                    "yhat": s.shift(lag_h, freq="h").reindex(s.index).to_numpy(),
                }
            )
        )
    return pd.concat(parts, ignore_index=True)


def _steps_per_day(freq: str) -> int:
    return int(pd.Timedelta(days=1) / step(freq))


