DINGLE_URL = "https://ndownloader.figshare.com/files/{file_id}"
DINGLE_PROVENANCE = Provenance(
    source="Dingle Peninsula houses, Ireland, 2020 (Khadem et al. 2024), H1-H20",
    license="CC0-1.0",
    citation=DINGLE_CITATION,
    url="https://doi.org/10.6084/m9.figshare.c.6829134",
)
_DINGLE_COLUMNS = {"generation": "Production(Wh)", "consumption": "Consumption(Wh)"}
_PARQUET_COLUMNS = {"generation": "prod_kWh", "consumption": "cons_kWh"}

Fetch = Callable[[str], bytes]


def dingle_houses(
    quantity: Literal["consumption", "generation"] = "consumption",
    *,
    houses: Iterable[int | str] | None = None,
    path: str | os.PathLike[str] | None = None,
    cache_dir: str | os.PathLike[str] | None = None,
    tz: Literal["Etc/GMT", "Europe/Dublin"] = "Etc/GMT",
    pv_only: bool = True,
    min_minutes: int = 55,
    get: Fetch | None = None,
) -> EnergySeries:
    """The 20 houses of the Dingle Peninsula (Ireland, 2020), hourly, in kWh: real, public example data.

    Source: Khadem et al. (2024), "Comprehensive Dataset on Electrical Load Profiles for Energy Community in
    Ireland", Scientific Data, doi:10.1038/s41597-024-03454-2; files on figshare,
    doi:10.6084/m9.figshare.c.6829134, licence CC0 (cite the paper: `DINGLE_CITATION`). These are the
    benchmark's `casas_*` cases. The series carries `DINGLE_PROVENANCE`, so `analyze` cites it.

    Where the data comes from, in order:
    - `path` to a FILE: the benchmark's `dados/casas_horario.parquet` (columns `casa`, `ds`, `prod_kWh`,
      `cons_kWh`), already hourly;
    - `path` to a DIRECTORY with the original `H<i>_Wh.csv` files;
    - otherwise the cache (`cache_dir`, default `$PROSUMER_DATA` or `~/.cache/prosumer`, subfolder
      `dingle`), downloading from figshare on first use (~28 MB per house, MD5 checked). `get(url)` returns
      the body; tests pass a fake one.

    From the 1-minute CSVs, as the benchmark's `01_prepara_dados.py`: each row is stamped by the END of its
    minute (01:01 ... 02:00 -> the hour starting 01:00), the hour is the sum of its minutes and is valid only
    with >= `min_minutes` of them (otherwise NaN, `valid` False); the grid is completed hourly. Battery, grid
    and state-of-charge columns are not read.

    Time zone (`tz`). The files are in Dublin local time on a GAP-FREE grid: the dataset's preprocessing
    filled the hour that does not exist (29/03 01:00) and kept a single row for the repeated one (25/10
    01:00); checked on 2026-10-07 by the PV of the 10 houses jumping ~1 h on 29/03.
    - "Etc/GMT" (default, the benchmark's choice): the local clock stamped as fixed UTC+0, every row kept,
      24 hours every day. Reproduces the benchmark exactly; in summer the absolute instant is 1 h off, which
      matters only when joining data in UTC (convert that data to the Dublin clock first, as the benchmark's
      `09_clima_casas.py` does with the station weather).
    - "Europe/Dublin": true instants; the two impossible rows per house are dropped (with a warning), so
      29/03 has 23 hours and 25/10 has a missing hour.

    `quantity="generation"` keeps, with `pv_only`, only the houses that produce anything in the period read
    (10 of the 20). House H14 ends ~20 days before the others (see `EnergySeries.end_per_series`).
    """
    if quantity not in _DINGLE_COLUMNS:
        raise ValueError("quantity must be 'consumption' or 'generation'")
    if tz not in ("Etc/GMT", "Europe/Dublin"):
        raise ValueError("tz must be 'Etc/GMT' (the benchmark's) or 'Europe/Dublin'")
    ids = _house_ids(houses)
    src = Path(path) if path is not None else None
    if src is not None and src.is_file():
        frame = _read_benchmark_parquet(src, quantity, ids)
    else:
        folder = src if src is not None else download_dingle_houses(ids, cache_dir=cache_dir, get=get)
        frame = pd.concat(
            [
                _read_dingle_csv(folder / f"{h}_Wh.csv", quantity, min_minutes).assign(unique_id=h)
                for h in ids
            ],
            ignore_index=True,
        )
    if quantity == "generation" and pv_only:
        total = frame.groupby("unique_id")["y"].sum()
        frame = frame[frame["unique_id"].isin(total[total > 0].index)]
        if frame.empty:
            raise ValueError("None of the houses asked for has PV generation")
    frame = frame[["unique_id", "ds", "y"]].assign(valid=lambda d: d["y"].notna())
    return EnergySeries.from_dataframe(
        frame.reset_index(drop=True),
        unit="kWh",
        quantity=quantity,
        tz=tz,
        freq="h",
        source_tz=tz if tz == "Etc/GMT" else "Europe/Dublin",
        dst="drop",
        provenance=DINGLE_PROVENANCE,
    )


def download_dingle_houses(
    houses: Iterable[int | str] | None = None,
    *,
    cache_dir: str | os.PathLike[str] | None = None,
    get: Fetch | None = None,
) -> Path:
    """Make sure `H<i>_Wh.csv` of each house is in the cache (MD5 checked) and return the folder.

    A file already there with the right MD5 is not downloaded again. Keep these files out of repositories:
    the licence (CC0) would allow it, the size (~560 MB for the 20) does not.
    """
    folder = _cache_root(cache_dir) / "dingle"
    folder.mkdir(parents=True, exist_ok=True)
    if get is None:
        from .io import _http

        get = _http.get_bytes
    for h in _house_ids(houses):
        file_id, md5 = DINGLE_FILES[h]
        target = folder / f"{h}_Wh.csv"
        if target.exists() and _md5(target.read_bytes()) == md5:
            continue
        body = get(DINGLE_URL.format(file_id=file_id))
        if _md5(body) != md5:
            raise RuntimeError(f"{h}_Wh.csv downloaded from figshare does not match its MD5 ({md5})")
        tmp = target.with_suffix(".part")
        tmp.write_bytes(body)
        tmp.replace(target)
    return folder


def _read_dingle_csv(file: Path, quantity: str, min_minutes: int) -> pd.DataFrame:
    """One house's 1-minute CSV -> naive local hours `ds`, `y` (kWh); see `dingle_houses`."""
    if not file.exists():
        raise FileNotFoundError(f"{file} not found (expected the dataset's H<i>_Wh.csv files)")
    x = pd.read_csv(file, skipinitialspace=True)
    x.columns = [c.strip() for c in x.columns]
    t = pd.to_datetime(x["date"])
    hour = (t - pd.Timedelta(minutes=1)).dt.floor("h")  # 01:01..02:00 -> 01:00
    g = pd.to_numeric(x[_DINGLE_COLUMNS[quantity]], errors="coerce").groupby(hour)
    y = g.sum(min_count=1).where(g.size() >= min_minutes) / 1000.0
    grid = pd.date_range(y.index.min(), y.index.max(), freq="h")
    return pd.DataFrame({"ds": grid, "y": y.reindex(grid).to_numpy(float)})


def _read_benchmark_parquet(file: Path, quantity: str, ids: list[str]) -> pd.DataFrame:
    c = pd.read_parquet(file, columns=["casa", "ds", _PARQUET_COLUMNS[quantity]])
    c = c[c["casa"].isin(ids)]
    if c.empty:
        raise ValueError(f"{file} has none of the houses {ids}")
    out = c.rename(columns={"casa": "unique_id", _PARQUET_COLUMNS[quantity]: "y"})
    return out.astype({"y": float})


def _house_ids(houses: Iterable[int | str] | None) -> list[str]:
    if houses is None:
        return list(DINGLE_FILES)
    ids = [f"H{h}" if isinstance(h, int) else str(h).upper() for h in houses]
    unknown = [h for h in ids if h not in DINGLE_FILES]
    if unknown:
        raise ValueError(f"Unknown houses {unknown}; the dataset has H1-H20")
    return ids


def _cache_root(cache_dir: str | os.PathLike[str] | None) -> Path:
    if cache_dir is not None:
        return Path(cache_dir)
    env = os.environ.get("PROSUMER_DATA")
    return Path(env) if env else Path.home() / ".cache" / "prosumer"


def _md5(body: bytes) -> str:
    return hashlib.md5(body, usedforsecurity=False).hexdigest()
